#!/usr/bin/env python3
"""Install FRECA candidate-generation / coverage-semantics correction v1.1.

Corrects two scaffold errors found by source-grounded diagnostics:

1. Full-case lexical scan was incorrectly interpreted as
   "every BM25 score > 0 becomes a candidate".
   v1.1 restores a bounded lexical candidate-generation rule while preserving
   full-case scan metadata.

2. coverage_v1 hard-coded FULL_CASE_SCAN even though current RetrievalNeed
   explicitly requests CANDIDATE_DISCOVERY.
   v1.1 reads the need's requested level and separates discovery completion from
   ProofStandard coverage.

Does NOT change:
  - FactCandidate semantics
  - identity policy
  - semantic alignment prompt/validator
  - Argument
  - ProofStandard gates
  - final fold
"""

from __future__ import annotations

import ast
import shutil
from pathlib import Path

EVIDENCE = Path(
    "evidence_reasoning_v2.py"
)

COVERAGE = Path(
    "coverage_v1.py"
)

NEW_RETRIEVE = '\ndef retrieve_requirement_candidates(\n    evidence_chunks: list[dict],\n    needs: list[dict],\n    *,\n    top_k: int = 12,\n) -> list[dict]:\n    """Retrieve with bounded candidate generation and separate context packing.\n\n    Important separation:\n      1. Every case record is scanned/scored by the enabled deterministic\n         channels.\n      2. A channel\'s frozen candidate-generation rule decides which records\n         become RetrievalHits / members of the candidate universe.\n      3. The candidate universe is persisted and is NOT truncated by model\n         context packing.\n      4. ``candidates`` remains the backward-compatible bounded model context.\n\n    This function deliberately does NOT treat every BM25 score > 0 as a\n    candidate.  The lexical channel scans the whole case but contributes a\n    frozen ranked prefix per QueryVariant.  This mirrors the reference-core\n    candidate_limit/top_k separation while keeping the full scan auditable.\n    """\n\n    from evidence_nature_v1 import (\n        classify_evidence_nature,\n        infer_requirement_predicate_profile,\n    )\n\n    docs = []\n    by_id = {}\n\n    for chunk in evidence_chunks:\n        cid = chunk_id(\n            chunk\n        )\n\n        text = chunk_text(\n            chunk\n        )\n\n        item = dict(\n            chunk\n        )\n\n        item[\n            "id"\n        ] = cid\n\n        item[\n            "text"\n        ] = text\n\n        docs.append(\n            item\n        )\n\n        by_id[\n            cid\n        ] = item\n\n    # These are retrieval configuration values, NOT proof thresholds.\n    lexical_candidate_limit = 40\n    per_variant_context_quota = 3\n    rrf_k = 60\n\n    support_context_cap = max(\n        24,\n        top_k,\n    )\n\n    attack_context_cap = max(\n        24,\n        top_k,\n    )\n\n    full_rank_cache = {}\n\n    def full_rank(\n        query: str,\n    ) -> list[dict]:\n        query = normalize_ws(\n            query\n        )\n\n        if not query:\n            return []\n\n        if (\n            query\n            not in full_rank_cache\n        ):\n            ranked = core.bm25_rank(\n                query,\n                docs,\n                len(\n                    docs\n                ),\n            )\n\n            # Preserve only positive lexical matches in the diagnostic full\n            # ranking.  The candidate universe is still bounded separately.\n            full_rank_cache[\n                query\n            ] = [\n                item\n                for item in ranked\n                if float(\n                    item.get(\n                        "score",\n                        0.0,\n                    )\n                    or 0.0\n                )\n                > 0.0\n            ]\n\n        return full_rank_cache[\n            query\n        ]\n\n    def neighbour_ids(\n        evidence_id: str,\n    ) -> list[str]:\n        out = []\n\n        paragraph = re.match(\n            r"^(.*):P(\\d+)$",\n            evidence_id,\n        )\n\n        if paragraph:\n            prefix = (\n                paragraph.group(\n                    1\n                )\n            )\n\n            number = int(\n                paragraph.group(\n                    2\n                )\n            )\n\n            for adjacent in (\n                number - 1,\n                number + 1,\n            ):\n                if adjacent >= 1:\n                    out.append(\n                        f"{prefix}:P{adjacent}"\n                    )\n\n            return out\n\n        row = re.match(\n            r"^(.*):R(\\d+)$",\n            evidence_id,\n        )\n\n        if row:\n            prefix = row.group(\n                1\n            )\n\n            number = int(\n                row.group(\n                    2\n                )\n            )\n\n            for adjacent in (\n                number - 1,\n                number + 1,\n            ):\n                if adjacent >= 1:\n                    out.append(\n                        f"{prefix}:R{adjacent}"\n                    )\n\n        return out\n\n    def rrf_order(\n        rankings: list[list[str]],\n    ) -> tuple[\n        list[str],\n        dict[str, float],\n    ]:\n        totals = {}\n        best_rank = {}\n        first_seen = {}\n        counter = 0\n\n        for ranking in rankings:\n            for rank, evidence_id in enumerate(\n                ranking,\n                start=1,\n            ):\n                totals[\n                    evidence_id\n                ] = (\n                    totals.get(\n                        evidence_id,\n                        0.0,\n                    )\n                    + 1.0\n                    / (\n                        rrf_k\n                        + rank\n                    )\n                )\n\n                best_rank[\n                    evidence_id\n                ] = min(\n                    best_rank.get(\n                        evidence_id,\n                        10**9,\n                    ),\n                    rank,\n                )\n\n                if (\n                    evidence_id\n                    not in first_seen\n                ):\n                    first_seen[\n                        evidence_id\n                    ] = counter\n\n                    counter += 1\n\n        ordered = sorted(\n            totals,\n            key=lambda evidence_id: (\n                -totals[\n                    evidence_id\n                ],\n                best_rank[\n                    evidence_id\n                ],\n                first_seen[\n                    evidence_id\n                ],\n                evidence_id,\n            ),\n        )\n\n        return (\n            ordered,\n            totals,\n        )\n\n    typed_natures_by_target = {\n        "DESIGN_CONSTRUCTION": {\n            "PHYSICAL_DESIGN_FEATURE",\n            "DESIGN_OR_CONSTRUCTION_DEFECT",\n        },\n        "CURRENT_CONDITION": {\n            "CURRENT_CONDITION",\n            "OBSERVATION_RECORD",\n            "REVIEW_FINDING",\n            "ACTIVITY_RECORD",\n            "CURRENT_MAINTENANCE_OR_CONDITION_DEFECT",\n            "ADVERSE_OPERATIONAL_FINDING",\n            "EXPLICIT_CONTROL_ABSENCE",\n        },\n        "ACTIVITY_PERFORMED": {\n            "ACTIVITY_RECORD",\n            "OBSERVATION_RECORD",\n            "REVIEW_FINDING",\n            "PROCEDURE_STATEMENT",\n            "PLAN_STATEMENT",\n        },\n        "RECORDKEEPING": {\n            "RECORD_EXISTS",\n            "ACTIVITY_RECORD",\n            "DOCUMENTATION_GAP",\n        },\n        "DOCUMENTATION": {\n            "RECORD_EXISTS",\n            "ACTIVITY_RECORD",\n            "DOCUMENTATION_GAP",\n        },\n        "PROCEDURE_OR_PLAN_EXISTS": {\n            "PROCEDURE_STATEMENT",\n            "PLAN_STATEMENT",\n            "DOCUMENTATION_GAP",\n        },\n        "OUTCOME_STATE": {\n            "CURRENT_CONDITION",\n            "OBSERVATION_RECORD",\n            "REVIEW_FINDING",\n            "CURRENT_MAINTENANCE_OR_CONDITION_DEFECT",\n            "ADVERSE_OPERATIONAL_FINDING",\n        },\n    }\n\n    typed_cache = {}\n\n    def typed_record(\n        item: dict,\n    ) -> dict:\n        evidence_id = item[\n            "id"\n        ]\n\n        if (\n            evidence_id\n            not in typed_cache\n        ):\n            typed_cache[\n                evidence_id\n            ] = (\n                classify_evidence_nature(\n                    item[\n                        "text"\n                    ]\n                )\n            )\n\n        return typed_cache[\n            evidence_id\n        ]\n\n    def typed_candidates_for_need(\n        need: dict,\n    ) -> tuple[\n        list[str],\n        dict,\n    ]:\n        facets = need.get(\n            "query_facets",\n            [],\n        )\n\n        proposition = (\n            facets[-1]\n            if facets\n            else ""\n        )\n\n        pseudo_requirement = {\n            "proposition_to_establish":\n                proposition,\n            "query_sources":\n                [],\n        }\n\n        profile = (\n            infer_requirement_predicate_profile(\n                pseudo_requirement\n            )\n        )\n\n        target_kinds = profile.get(\n            "target_kinds",\n            [],\n        )\n\n        wanted = set()\n\n        for target_kind in target_kinds:\n            wanted.update(\n                typed_natures_by_target.get(\n                    target_kind,\n                    set(),\n                )\n            )\n\n        matched = []\n\n        if wanted:\n            for item in docs:\n                typed = typed_record(\n                    item\n                )\n\n                natures = set(\n                    typed.get(\n                        "evidence_natures",\n                        [],\n                    )\n                )\n\n                if (\n                    natures\n                    & wanted\n                ):\n                    matched.append(\n                        item[\n                            "id"\n                        ]\n                    )\n\n        return (\n            matched,\n            {\n                "target_kinds":\n                    target_kinds,\n                "wanted_natures":\n                    sorted(\n                        wanted\n                    ),\n                "scan_chunk_count":\n                    len(\n                        docs\n                    ),\n                "matched_count":\n                    len(\n                        matched\n                    ),\n                "full_case_scan":\n                    True,\n                "candidate_generation_mode":\n                    "ALL_TYPED_MATCHES",\n            },\n        )\n\n    traces = []\n\n    for need in needs:\n        combined_query = (\n            _build_query(\n                need[\n                    "query_facets"\n                ]\n            )\n        )\n\n        source_variants = list(\n            need.get(\n                "query_variants",\n                [],\n            )\n        )\n\n        if not source_variants:\n            source_variants = [\n                {\n                    "variant_id":\n                        (\n                            f"{need[\'need_id\']}"\n                            ".fallback"\n                        ),\n                    "source":\n                        "COMBINED",\n                    "candidate_id":\n                        None,\n                    "query":\n                        combined_query,\n                    "transformation":\n                        "COMBINED_FALLBACK",\n                }\n            ]\n\n        variant_rows = []\n        lexical_rankings = []\n        lexical_ids = []\n        lexical_seen = set()\n        lexical_best_score = {}\n\n        # ------------------------------------------------------------\n        # RAW_LEXICAL:\n        # scan the full case, but generate a bounded RetrievalHit set.\n        # ------------------------------------------------------------\n        for variant in source_variants:\n            query = normalize_ws(\n                variant.get(\n                    "query",\n                    "",\n                )\n            )\n\n            if not query:\n                continue\n\n            full_ranked = full_rank(\n                query\n            )\n\n            generated = full_ranked[\n                :lexical_candidate_limit\n            ]\n\n            generated_ids = [\n                item[\n                    "id"\n                ]\n                for item\n                in generated\n            ]\n\n            lexical_rankings.append(\n                generated_ids\n            )\n\n            for item in generated:\n                evidence_id = item[\n                    "id"\n                ]\n\n                lexical_best_score[\n                    evidence_id\n                ] = max(\n                    lexical_best_score.get(\n                        evidence_id,\n                        0.0,\n                    ),\n                    float(\n                        item.get(\n                            "score",\n                            0.0,\n                        )\n                        or 0.0\n                    ),\n                )\n\n                if (\n                    evidence_id\n                    not in lexical_seen\n                ):\n                    lexical_seen.add(\n                        evidence_id\n                    )\n\n                    lexical_ids.append(\n                        evidence_id\n                    )\n\n            variant_rows.append(\n                {\n                    **variant,\n                    "scan_chunk_count":\n                        len(\n                            docs\n                        ),\n                    "scan_complete":\n                        True,\n                    "positive_score_count":\n                        len(\n                            full_ranked\n                        ),\n                    "candidate_limit":\n                        lexical_candidate_limit,\n                    "generated_candidate_count":\n                        len(\n                            generated_ids\n                        ),\n                    "generated_candidate_ids":\n                        generated_ids,\n                    # Backward-compatible ranking/context field.\n                    "top_ids":\n                        generated_ids[\n                            :per_variant_context_quota\n                        ],\n                }\n            )\n\n        (\n            fused_lexical_ids,\n            rrf_scores,\n        ) = rrf_order(\n            lexical_rankings\n        )\n\n        (\n            typed_ids,\n            typed_trace,\n        ) = typed_candidates_for_need(\n            need\n        )\n\n        # ------------------------------------------------------------\n        # Candidate universe:\n        # lexical generated hits + all typed hits + bounded structure rescue.\n        # ------------------------------------------------------------\n        universe_ids = []\n        methods_by_id = {}\n\n        def add_universe(\n            evidence_id: str,\n            method: str,\n        ) -> None:\n            if (\n                evidence_id\n                not in by_id\n            ):\n                return\n\n            methods_by_id.setdefault(\n                evidence_id,\n                [],\n            )\n\n            if (\n                method\n                not in methods_by_id[\n                    evidence_id\n                ]\n            ):\n                methods_by_id[\n                    evidence_id\n                ].append(\n                    method\n                )\n\n            if (\n                evidence_id\n                not in universe_ids\n            ):\n                universe_ids.append(\n                    evidence_id\n                )\n\n        for evidence_id in lexical_ids:\n            add_universe(\n                evidence_id,\n                "LEXICAL_BM25_GENERATED_HIT",\n            )\n\n        for evidence_id in typed_ids:\n            add_universe(\n                evidence_id,\n                "TYPED_FACT_SCAN",\n            )\n\n        # STRUCTURE remains a rescue channel in Core v1.1:\n        # only high-priority lexical seeds and typed hits seed neighbours.\n        structure_seed_ids = []\n\n        def add_structure_seed(\n            evidence_id: str,\n        ) -> None:\n            if (\n                evidence_id\n                in by_id\n                and evidence_id\n                not in structure_seed_ids\n            ):\n                structure_seed_ids.append(\n                    evidence_id\n                )\n\n        for variant in variant_rows:\n            for evidence_id in variant[\n                "top_ids"\n            ]:\n                add_structure_seed(\n                    evidence_id\n                )\n\n        for evidence_id in typed_ids:\n            add_structure_seed(\n                evidence_id\n            )\n\n        structure_added_ids = []\n\n        for evidence_id in structure_seed_ids:\n            for neighbour_id in neighbour_ids(\n                evidence_id\n            ):\n                before = (\n                    neighbour_id\n                    in universe_ids\n                )\n\n                add_universe(\n                    neighbour_id,\n                    "STRUCTURE_NEIGHBOUR",\n                )\n\n                if (\n                    neighbour_id\n                    in by_id\n                    and not before\n                    and neighbour_id\n                    not in structure_added_ids\n                ):\n                    structure_added_ids.append(\n                        neighbour_id\n                    )\n\n        candidate_universe = []\n\n        for universe_rank, evidence_id in enumerate(\n            universe_ids,\n            start=1,\n        ):\n            item = by_id[\n                evidence_id\n            ]\n\n            candidate_universe.append(\n                {\n                    "evidence_id":\n                        evidence_id,\n                    "score":\n                        rrf_scores.get(\n                            evidence_id\n                        ),\n                    "lexical_best_score":\n                        lexical_best_score.get(\n                            evidence_id\n                        ),\n                    "text":\n                        item[\n                            "text"\n                        ],\n                    "retrieval_methods":\n                        methods_by_id.get(\n                            evidence_id,\n                            [],\n                        ),\n                    "universe_rank":\n                        universe_rank,\n                }\n            )\n\n        # ------------------------------------------------------------\n        # Model context: bounded ordering only.\n        # ------------------------------------------------------------\n        context_cap = (\n            support_context_cap\n            if need[\n                "direction"\n            ]\n            == "SUPPORT"\n            else attack_context_cap\n        )\n\n        context_ids = []\n\n        def add_context(\n            evidence_id: str,\n        ) -> None:\n            if (\n                evidence_id\n                not in by_id\n            ):\n                return\n\n            if (\n                evidence_id\n                not in context_ids\n            ):\n                context_ids.append(\n                    evidence_id\n                )\n\n        # Typed first because it is the strongest deterministic\n        # predicate-oriented retrieval view currently implemented.\n        for evidence_id in typed_ids:\n            add_context(\n                evidence_id\n            )\n\n        # Frozen source-grounded quota.\n        for variant in variant_rows:\n            for evidence_id in variant[\n                "top_ids"\n            ]:\n                add_context(\n                    evidence_id\n                )\n\n                for neighbour_id in neighbour_ids(\n                    evidence_id\n                ):\n                    add_context(\n                        neighbour_id\n                    )\n\n        # RRF ordering only decides when an unresolved candidate is seen.\n        for evidence_id in fused_lexical_ids:\n            if (\n                len(\n                    context_ids\n                )\n                >= context_cap\n            ):\n                break\n\n            add_context(\n                evidence_id\n            )\n\n        context_ids = context_ids[\n            :context_cap\n        ]\n\n        universe_by_id = {\n            row[\n                "evidence_id"\n            ]: row\n            for row\n            in candidate_universe\n        }\n\n        candidates = []\n\n        for context_rank, evidence_id in enumerate(\n            context_ids,\n            start=1,\n        ):\n            if (\n                evidence_id\n                not in universe_by_id\n            ):\n                continue\n\n            row = dict(\n                universe_by_id[\n                    evidence_id\n                ]\n            )\n\n            row[\n                "context_rank"\n            ] = context_rank\n\n            row[\n                "selected_for_model_context"\n            ] = True\n\n            candidates.append(\n                row\n            )\n\n        # Initial Core needs are discovery needs.  Do not silently upgrade them.\n        coverage_requirement = need.get(\n            "coverage_requirement",\n            "CANDIDATE_DISCOVERY",\n        )\n\n        traces.append(\n            {\n                **need,\n                "coverage_requirement":\n                    coverage_requirement,\n                "query":\n                    combined_query,\n                "query_plan_mode":\n                    (\n                        "BOUNDED_CANDIDATE_UNIVERSE_"\n                        "PLUS_CONTEXT_PACKING_V1_1"\n                    ),\n\n                "expected_channels": [\n                    "RAW_LEXICAL",\n                    "TYPED_FACT",\n                    "STRUCTURE",\n                ],\n\n                "query_variants":\n                    variant_rows,\n\n                "raw_lexical_scan": {\n                    "scan_chunk_count":\n                        len(\n                            docs\n                        ),\n                    "scan_complete":\n                        True,\n                    "candidate_generation_mode":\n                        "TOP_K_PER_VARIANT",\n                    "candidate_limit_per_variant":\n                        lexical_candidate_limit,\n                    "generated_union_count":\n                        len(\n                            lexical_ids\n                        ),\n                },\n\n                "typed_fact_scan":\n                    typed_trace,\n\n                "structure_scan": {\n                    "mode":\n                        "SEED_NEIGHBOUR_RESCUE_ONLY",\n                    "scan_chunk_count":\n                        len(\n                            docs\n                        ),\n                    "seed_count":\n                        len(\n                            structure_seed_ids\n                        ),\n                    "generated_candidate_count":\n                        len(\n                            structure_added_ids\n                        ),\n                    "generated_candidate_ids":\n                        structure_added_ids,\n                    "full_scan":\n                        False,\n                    "executed":\n                        True,\n                },\n\n                "candidate_universe_persisted":\n                    True,\n                "candidate_universe_ids":\n                    universe_ids,\n                "candidate_universe_count":\n                    len(\n                        universe_ids\n                    ),\n                "candidate_universe":\n                    candidate_universe,\n\n                "model_context_candidate_ids":\n                    context_ids,\n                "model_context_count":\n                    len(\n                        context_ids\n                    ),\n                "model_context_cap":\n                    context_cap,\n\n                # Backward-compatible context field used by current alignment.\n                "candidates":\n                    candidates,\n                "candidate_count_checked_by_model":\n                    len(\n                        candidates\n                    ),\n\n                "candidate_limit":\n                    lexical_candidate_limit,\n                "per_variant_quota":\n                    per_variant_context_quota,\n                (\n                    "support_context_cap"\n                    if need[\n                        "direction"\n                    ]\n                    == "SUPPORT"\n                    else "attack_context_cap"\n                ):\n                    context_cap,\n\n                "retrieval_scan_chunk_count":\n                    len(\n                        docs\n                    ),\n\n                "coverage_status":\n                    "DISCOVERY_TRACE_V1_1",\n            }\n        )\n\n    return traces\n'
NEW_LEXICAL_CHANNEL = '\ndef lexical_channel(\n    trace: dict,\n) -> dict:\n    """Audit execution of RAW_LEXICAL without equating all positive scores to candidates."""\n\n    raw = trace.get(\n        "raw_lexical_scan"\n    )\n\n    variants = trace.get(\n        "query_variants",\n        [],\n    )\n\n    if isinstance(\n        raw,\n        dict,\n    ):\n        scan_count = int(\n            raw.get(\n                "scan_chunk_count",\n                0,\n            )\n            or 0\n        )\n\n        scan_complete = bool(\n            raw.get(\n                "scan_complete",\n                False,\n            )\n        )\n\n        generated_union_count = int(\n            raw.get(\n                "generated_union_count",\n                0,\n            )\n            or 0\n        )\n\n        mode = str(\n            raw.get(\n                "candidate_generation_mode",\n                "UNKNOWN",\n            )\n        )\n\n    else:\n        scan_count = int(\n            trace.get(\n                "retrieval_scan_chunk_count",\n                0,\n            )\n            or 0\n        )\n\n        scan_complete = bool(\n            variants\n        )\n\n        generated_union_count = 0\n\n        mode = (\n            "LEGACY_VARIANT_TRACE"\n        )\n\n    return {\n        "channel":\n            "RAW_LEXICAL",\n        "executed":\n            bool(\n                variants\n            ),\n        "mode":\n            mode,\n        "scanned_record_count":\n            scan_count,\n        "scan_complete":\n            scan_complete,\n        "generated_candidate_count":\n            generated_union_count,\n        "candidate_limit_per_variant":\n            (\n                raw.get(\n                    "candidate_limit_per_variant"\n                )\n                if isinstance(\n                    raw,\n                    dict,\n                )\n                else trace.get(\n                    "candidate_limit"\n                )\n            ),\n        "complete_for_candidate_discovery":\n            bool(\n                variants\n                and scan_complete\n            ),\n    }\n'
NEW_TYPED_CHANNEL = '\ndef typed_channel(\n    trace: dict,\n) -> dict:\n    typed = trace.get(\n        "typed_fact_scan"\n    )\n\n    if not isinstance(\n        typed,\n        dict,\n    ):\n        return {\n            "channel":\n                "TYPED_FACT",\n            "executed":\n                False,\n            "mode":\n                "NOT_EXECUTED",\n            "scanned_record_count":\n                0,\n            "matched_count":\n                0,\n            "complete_for_candidate_discovery":\n                False,\n        }\n\n    scan_count = int(\n        typed.get(\n            "scan_chunk_count",\n            0,\n        )\n        or 0\n    )\n\n    full_case_count = int(\n        trace.get(\n            "retrieval_scan_chunk_count",\n            0,\n        )\n        or 0\n    )\n\n    matched_count = int(\n        typed.get(\n            "matched_count",\n            0,\n        )\n        or 0\n    )\n\n    full_scan = bool(\n        typed.get(\n            "full_case_scan",\n            False,\n        )\n        or (\n            scan_count > 0\n            and (\n                full_case_count == 0\n                or scan_count\n                == full_case_count\n            )\n        )\n    )\n\n    return {\n        "channel":\n            "TYPED_FACT",\n        "executed":\n            True,\n        "mode":\n            (\n                "FULL_CASE_SCAN"\n                if full_scan\n                else "PARTIAL_SCAN"\n            ),\n        "scanned_record_count":\n            scan_count,\n        "matched_count":\n            matched_count,\n        "target_kinds":\n            typed.get(\n                "target_kinds",\n                [],\n            ),\n        "wanted_natures":\n            typed.get(\n                "wanted_natures",\n                [],\n            ),\n        "complete_for_candidate_discovery":\n            full_scan,\n    }\n'
NEW_STRUCTURE_CHANNEL = '\ndef structure_channel(\n    trace: dict,\n) -> dict:\n    structure = (\n        trace.get(\n            "structure_scan"\n        )\n        or {}\n    )\n\n    universe = trace.get(\n        "candidate_universe"\n    )\n\n    if not isinstance(\n        universe,\n        list,\n    ):\n        universe = trace.get(\n            "candidates",\n            [],\n        )\n\n    neighbour_hits = [\n        candidate\n        for candidate\n        in universe\n        if (\n            "STRUCTURE_NEIGHBOUR"\n            in candidate.get(\n                "retrieval_methods",\n                [],\n            )\n        )\n    ]\n\n    executed = bool(\n        structure.get(\n            "executed",\n            False,\n        )\n        or neighbour_hits\n    )\n\n    mode = str(\n        structure.get(\n            "mode",\n            (\n                "SEED_NEIGHBOUR_RESCUE_ONLY"\n                if neighbour_hits\n                else "NOT_EXECUTED"\n            ),\n        )\n    )\n\n    return {\n        "channel":\n            "STRUCTURE",\n        "executed":\n            executed,\n        "mode":\n            mode,\n        "scanned_record_count":\n            int(\n                structure.get(\n                    "scan_chunk_count",\n                    0,\n                )\n                or 0\n            ),\n        "seed_count":\n            int(\n                structure.get(\n                    "seed_count",\n                    0,\n                )\n                or 0\n            ),\n        "generated_candidate_count":\n            int(\n                structure.get(\n                    "generated_candidate_count",\n                    len(\n                        neighbour_hits\n                    ),\n                )\n                or 0\n            ),\n        # For CANDIDATE_DISCOVERY we require the registered structure procedure\n        # to execute; we do NOT pretend neighbour rescue is a full structural\n        # population scan.\n        "complete_for_candidate_discovery":\n            executed,\n        "full_scan":\n            bool(\n                structure.get(\n                    "full_scan",\n                    False,\n                )\n            ),\n    }\n'
NEW_EVALUATE_NEED = '\ndef evaluate_need_coverage(\n    *,\n    trace: dict,\n    alignments: list[dict],\n) -> dict:\n    """Evaluate the CURRENT need at the level requested by the need itself.\n\n    Initial Core v1 needs use CANDIDATE_DISCOVERY.  That level can be\n    procedurally complete without being sufficient for ProofStandard.\n\n    This function therefore separates:\n      - procedure_complete: did the registered discovery procedure run?\n      - candidate_disposition_complete: were generated candidates disposed?\n      - proof_coverage_pass: is the achieved level sufficient for proof?\n    """\n\n    need_id = str(\n        trace.get(\n            "need_id",\n            "",\n        )\n    )\n\n    requirement_id = str(\n        trace.get(\n            "requirement_id",\n            "",\n        )\n    )\n\n    direction = str(\n        trace.get(\n            "direction",\n            "",\n        )\n    )\n\n    required_level = str(\n        trace.get(\n            "coverage_requirement",\n            "CANDIDATE_DISCOVERY",\n        )\n    )\n\n    lexical = lexical_channel(\n        trace\n    )\n\n    typed = typed_channel(\n        trace\n    )\n\n    structure = structure_channel(\n        trace\n    )\n\n    channels = {\n        item[\n            "channel"\n        ]: item\n        for item in (\n            lexical,\n            typed,\n            structure,\n        )\n    }\n\n    expected_channels = list(\n        trace.get(\n            "expected_channels",\n            REQUIRED_CHANNELS,\n        )\n        or REQUIRED_CHANNELS\n    )\n\n    disposition = (\n        candidate_disposition(\n            trace=\n                trace,\n            alignments=\n                alignments,\n        )\n    )\n\n    candidate_universe_preserved = bool(\n        trace.get(\n            "candidate_universe_persisted",\n            False,\n        )\n    )\n\n    executed_channels = [\n        name\n        for name in expected_channels\n        if (\n            name in channels\n            and channels[\n                name\n            ][\n                "executed"\n            ]\n        )\n    ]\n\n    failed_channels = []\n    limiting_factors = []\n\n    if (\n        required_level\n        == "CANDIDATE_DISCOVERY"\n    ):\n        for name in expected_channels:\n            channel = channels.get(\n                name\n            )\n\n            if channel is None:\n                failed_channels.append(\n                    name\n                )\n                limiting_factors.append(\n                    f"{name}_CHANNEL_MISSING"\n                )\n                continue\n\n            if not channel.get(\n                "complete_for_candidate_discovery",\n                False,\n            ):\n                failed_channels.append(\n                    name\n                )\n                limiting_factors.append(\n                    f"{name}_DISCOVERY_PROCEDURE_INCOMPLETE"\n                )\n\n        procedure_complete = bool(\n            not failed_channels\n            and candidate_universe_preserved\n        )\n\n        achieved_level = (\n            "CANDIDATE_DISCOVERY"\n            if procedure_complete\n            else "NONE"\n        )\n\n    else:\n        # Higher coverage levels require an explicit ProcedureObjective /\n        # PopulationFrame contract.  Do not invent semantics here.\n        procedure_complete = False\n        achieved_level = (\n            "CANDIDATE_DISCOVERY"\n            if candidate_universe_preserved\n            else "NONE"\n        )\n\n        limiting_factors.append(\n            "HIGHER_COVERAGE_PROCEDURE_OBJECTIVE_NOT_IMPLEMENTED"\n        )\n\n    if not candidate_universe_preserved:\n        limiting_factors.append(\n            "CANDIDATE_UNIVERSE_NOT_PERSISTED"\n        )\n\n    unassessed = disposition[\n        "universe_unassessed_candidate_ids"\n    ]\n\n    candidate_disposition_complete = (\n        len(\n            unassessed\n        )\n        == 0\n    )\n\n    if not candidate_disposition_complete:\n        limiting_factors.append(\n            "CANDIDATE_UNIVERSE_NOT_FULLY_ASSESSED"\n        )\n\n    universe_count = disposition[\n        "candidate_universe_count"\n    ]\n\n    context_count = disposition[\n        "context_selected_count"\n    ]\n\n    context_cap = int(\n        trace.get(\n            "model_context_cap",\n            trace.get(\n                "support_context_cap",\n                trace.get(\n                    "attack_context_cap",\n                    trace.get(\n                        "top_k",\n                        0,\n                    ),\n                ),\n            ),\n        )\n        or 0\n    )\n\n    context_packing_status = (\n        "ALL_UNIVERSE_IN_CONTEXT"\n        if universe_count\n        <= context_count\n        else "PARTIAL_CONTEXT_BATCH"\n    )\n\n    identity_gap_ids = (\n        disposition[\n            "universe_conditional_candidate_ids"\n        ]\n    )\n\n    parse_gap_ids = list(\n        trace.get(\n            "parse_gap_ids",\n            [],\n        )\n        or []\n    )\n\n    missing_required_track_types = list(\n        trace.get(\n            "missing_required_track_types",\n            [],\n        )\n        or []\n    )\n\n    if parse_gap_ids:\n        status = (\n            "INCOMPLETE_PARSE"\n        )\n\n    elif missing_required_track_types:\n        status = (\n            "INCOMPLETE_MISSING_SOURCE"\n        )\n\n    elif failed_channels:\n        status = (\n            "INCOMPLETE_CHANNEL_FAILURE"\n        )\n\n    elif (\n        not candidate_universe_preserved\n    ):\n        status = (\n            "ERROR"\n        )\n\n    elif (\n        not candidate_disposition_complete\n    ):\n        status = (\n            "LIMITED_TOP_K"\n        )\n\n    else:\n        has_relevant_alignment = any(\n            (\n                row.get(\n                    "relation"\n                )\n                in {\n                    "SUPPORT",\n                    "ATTACK",\n                }\n            )\n            and need_id\n            in (\n                row.get(\n                    "retrieval_need_ids",\n                    [],\n                )\n                or []\n            )\n            for row in alignments\n        )\n\n        status = (\n            "COMPLETE"\n            if has_relevant_alignment\n            else "COMPLETE_NO_RELEVANT_HIT"\n        )\n\n    # CANDIDATE_DISCOVERY is intentionally not enough for D7.14 proof.\n    proof_coverage_pass = False\n\n    if (\n        required_level\n        != "CANDIDATE_DISCOVERY"\n    ):\n        limiting_factors.append(\n            "REQUESTED_COVERAGE_LEVEL_NOT_YET_SATISFIED"\n        )\n    else:\n        limiting_factors.append(\n            "CANDIDATE_DISCOVERY_NOT_PROOF_COVERAGE"\n        )\n\n    report = {\n        "coverage_id":\n            stable_id(\n                requirement_id,\n                need_id,\n                direction,\n            ),\n        "need_id":\n            need_id,\n        "requirement_id":\n            requirement_id,\n        "direction":\n            direction,\n\n        "required_level":\n            required_level,\n        "achieved_level":\n            achieved_level,\n\n        "procedure_complete":\n            procedure_complete,\n        "candidate_disposition_complete":\n            candidate_disposition_complete,\n        "proof_coverage_pass":\n            proof_coverage_pass,\n\n        # Backward-compatible alias: never let discovery-only coverage satisfy\n        # ProofStandard accidentally.\n        "coverage_pass":\n            proof_coverage_pass,\n\n        "conclusion_scope":\n            "SOURCE_PACKAGE_ONLY",\n\n        "indexed_record_count":\n            int(\n                trace.get(\n                    "retrieval_scan_chunk_count",\n                    0,\n                )\n                or 0\n            ),\n        "searchable_record_count":\n            int(\n                trace.get(\n                    "retrieval_scan_chunk_count",\n                    0,\n                )\n                or 0\n            ),\n        "scanned_record_count":\n            max(\n                int(\n                    lexical.get(\n                        "scanned_record_count",\n                        0,\n                    )\n                    or 0\n                ),\n                int(\n                    typed.get(\n                        "scanned_record_count",\n                        0,\n                    )\n                    or 0\n                ),\n                int(\n                    structure.get(\n                        "scanned_record_count",\n                        0,\n                    )\n                    or 0\n                ),\n            ),\n\n        "query_plan_mode":\n            trace.get(\n                "query_plan_mode"\n            ),\n        "expected_channels":\n            expected_channels,\n        "executed_channels":\n            executed_channels,\n        "failed_channels":\n            failed_channels,\n        "channel_reports":\n            channels,\n\n        "candidate_count":\n            universe_count,\n        "candidate_universe_preserved":\n            candidate_universe_preserved,\n\n        "model_context_count":\n            context_count,\n        "model_context_cap":\n            context_cap,\n        "context_packing_status":\n            context_packing_status,\n\n        "deterministically_assessed_count":\n            len(\n                disposition[\n                    "universe_excluded_candidate_ids"\n                ]\n            ),\n        "model_or_rule_assessed_count":\n            len(\n                disposition[\n                    "model_or_rule_assessed_parent_ids"\n                ]\n            ),\n        "unassessed_candidate_ids":\n            unassessed,\n\n        "direct_alignment_ids": [\n            alignment_id(\n                row\n            )\n            for row in alignments\n            if (\n                need_id\n                in (\n                    row.get(\n                        "retrieval_need_ids",\n                        [],\n                    )\n                    or []\n                )\n                and row.get(\n                    "argument_admission_channel"\n                )\n                == "DIRECT"\n            )\n        ],\n\n        "conditional_alignment_ids": [\n            alignment_id(\n                row\n            )\n            for row in alignments\n            if (\n                need_id\n                in (\n                    row.get(\n                        "retrieval_need_ids",\n                        [],\n                    )\n                    or []\n                )\n                and row.get(\n                    "argument_admission_channel"\n                )\n                == "CONDITIONAL"\n            )\n        ],\n\n        "excluded_hit_ids":\n            disposition[\n                "universe_excluded_candidate_ids"\n            ],\n\n        "parse_gap_ids":\n            parse_gap_ids,\n        "identity_gap_ids":\n            identity_gap_ids,\n        "missing_required_track_types":\n            missing_required_track_types,\n\n        "status":\n            status,\n        "limiting_factors":\n            sorted(\n                set(\n                    limiting_factors\n                )\n            ),\n\n        "policy_notes": [\n            "coverage level comes from RetrievalNeed, not the evaluator",\n            "full-case scan does not mean every positive BM25 score is a candidate",\n            "candidate universe and model context remain separate",\n            "CANDIDATE_DISCOVERY never satisfies ProofStandard coverage",\n            "higher coverage requires an explicit ProcedureObjective/PopulationFrame",\n        ],\n    }\n\n    report[\n        "coverage_sha256"\n    ] = sha256_json(\n        report\n    )\n\n    return report\n'
NEW_EVALUATE_BUNDLE = '\ndef evaluate_coverage_bundle(\n    requirement_result: dict,\n) -> dict:\n    traces = (\n        requirement_result.get(\n            "retrieval_traces",\n            []\n        )\n    )\n\n    alignments = (\n        requirement_result.get(\n            "alignments",\n            []\n        )\n    )\n\n    reports = [\n        evaluate_need_coverage(\n            trace=\n                trace,\n            alignments=\n                alignments,\n        )\n        for trace in traces\n    ]\n\n    by_requirement = {}\n\n    for report in reports:\n        by_requirement.setdefault(\n            report[\n                "requirement_id"\n            ],\n            [],\n        ).append(\n            report\n        )\n\n    requirement_summaries = []\n\n    for rid, group in sorted(\n        by_requirement.items()\n    ):\n        support = [\n            report\n            for report in group\n            if report[\n                "direction"\n            ]\n            == "SUPPORT"\n        ]\n\n        attack = [\n            report\n            for report in group\n            if report[\n                "direction"\n            ]\n            == "ATTACK"\n        ]\n\n        bidirectional_discovery_complete = bool(\n            support\n            and attack\n            and all(\n                report[\n                    "procedure_complete"\n                ]\n                for report in (\n                    support\n                    + attack\n                )\n            )\n        )\n\n        proof_coverage_pass = bool(\n            support\n            and attack\n            and all(\n                report[\n                    "proof_coverage_pass"\n                ]\n                for report in (\n                    support\n                    + attack\n                )\n            )\n        )\n\n        requirement_summaries.append(\n            {\n                "requirement_id":\n                    rid,\n                "support_need_present":\n                    bool(\n                        support\n                    ),\n                "attack_need_present":\n                    bool(\n                        attack\n                    ),\n\n                "requested_levels":\n                    sorted(\n                        {\n                            report[\n                                "required_level"\n                            ]\n                            for report in group\n                        }\n                    ),\n\n                "support_statuses": [\n                    report[\n                        "status"\n                    ]\n                    for report in support\n                ],\n                "attack_statuses": [\n                    report[\n                        "status"\n                    ]\n                    for report in attack\n                ],\n\n                "bidirectional_discovery_complete":\n                    bidirectional_discovery_complete,\n                "proof_coverage_pass":\n                    proof_coverage_pass,\n\n                "coverage_status":\n                    (\n                        "PROOF_COVERAGE_COMPLETE"\n                        if proof_coverage_pass\n                        else (\n                            "DISCOVERY_COMPLETE_PROOF_PENDING"\n                            if bidirectional_discovery_complete\n                            else "DISCOVERY_INCOMPLETE"\n                        )\n                    ),\n\n                "limiting_factors":\n                    sorted(\n                        {\n                            factor\n                            for report in group\n                            for factor in report[\n                                "limiting_factors"\n                            ]\n                        }\n                    ),\n            }\n        )\n\n    discovery_complete = bool(\n        requirement_summaries\n        and all(\n            item[\n                "bidirectional_discovery_complete"\n            ]\n            for item in requirement_summaries\n        )\n    )\n\n    proof_coverage_complete = bool(\n        requirement_summaries\n        and all(\n            item[\n                "proof_coverage_pass"\n            ]\n            for item in requirement_summaries\n        )\n    )\n\n    bundle = {\n        "schema":\n            "freca-core-requirement-coverage-v1.1",\n        "cp_id":\n            requirement_result.get(\n                "cp_id"\n            ),\n        "case_id":\n            requirement_result.get(\n                "case_id"\n            ),\n\n        "coverage_policy": {\n            "initial_need_level":\n                "CANDIDATE_DISCOVERY",\n            "top_k_never_means_complete":\n                True,\n            "candidate_universe_is_generated_hits_not_all_positive_bm25_scores":\n                True,\n            "proof_requires_explicit_higher_coverage_objective":\n                True,\n        },\n\n        "need_reports":\n            reports,\n        "requirement_summaries":\n            requirement_summaries,\n\n        "discovery_complete":\n            discovery_complete,\n        "proof_coverage_complete":\n            proof_coverage_complete,\n\n        # Backward-compatible aliases consumed by existing ProofStandard:\n        # do not allow discovery-only completion to leak into proof.\n        "coverage_complete":\n            proof_coverage_complete,\n        "coverage_pass":\n            proof_coverage_complete,\n\n        "adverse_inference_allowed":\n            False,\n        "burden_rule_applied":\n            False,\n\n        "next_required_artifact":\n            (\n                "TARGETED_COMPLETE_PROCEDURE_OBJECTIVE"\n                if discovery_complete\n                and not proof_coverage_complete\n                else None\n            ),\n\n        "notes": [\n            (\n                "Initial Core retrieval needs are CANDIDATE_DISCOVERY; "\n                "this artifact no longer upgrades them to FULL_CASE_SCAN."\n            ),\n            (\n                "Full-case lexical scoring is recorded as procedure execution; "\n                "only the frozen ranked candidate limit becomes RetrievalHits."\n            ),\n            (\n                "A later explicit ProcedureObjective/PopulationFrame is required "\n                "before TARGETED_COMPLETE or higher coverage can be claimed."\n            ),\n        ],\n    }\n\n    bundle[\n        "bundle_sha256"\n    ] = sha256_json(\n        bundle\n    )\n\n    return bundle\n'
NEW_SELF_TESTS = '\ndef run_self_tests() -> None:\n    def make_trace(\n        *,\n        unassessed: bool,\n        missing_channel: bool = False,\n        level: str = "CANDIDATE_DISCOVERY",\n    ) -> dict:\n        expected = [\n            "RAW_LEXICAL",\n            "TYPED_FACT",\n            "STRUCTURE",\n        ]\n\n        trace = {\n            "need_id":\n                "ERX.support",\n            "requirement_id":\n                "ERX",\n            "direction":\n                "SUPPORT",\n            "coverage_requirement":\n                level,\n            "expected_channels":\n                expected,\n            "retrieval_scan_chunk_count":\n                10,\n            "raw_lexical_scan": {\n                "scan_chunk_count":\n                    10,\n                "scan_complete":\n                    True,\n                "candidate_generation_mode":\n                    "TOP_K_PER_VARIANT",\n                "candidate_limit_per_variant":\n                    4,\n                "generated_union_count":\n                    1,\n            },\n            "query_variants": [\n                {\n                    "variant_id":\n                        "v1",\n                    "query":\n                        "fixture",\n                    "scan_complete":\n                        True,\n                }\n            ],\n            "typed_fact_scan": {\n                "scan_chunk_count":\n                    10,\n                "matched_count":\n                    1,\n                "full_case_scan":\n                    True,\n            },\n            "structure_scan": {\n                "mode":\n                    "SEED_NEIGHBOUR_RESCUE_ONLY",\n                "scan_chunk_count":\n                    10,\n                "seed_count":\n                    1,\n                "generated_candidate_count":\n                    0,\n                "full_scan":\n                    False,\n                "executed":\n                    not missing_channel,\n            },\n            "candidate_universe_persisted":\n                True,\n            "candidate_universe": [\n                {\n                    "evidence_id":\n                        "e1",\n                    "identity_use_decision":\n                        "ADMIT_DIRECT",\n                    "retrieval_methods":\n                        [\n                            "TYPED_FACT_SCAN",\n                        ],\n                }\n            ],\n            "candidate_universe_ids":\n                [\n                    "e1",\n                ],\n            "candidates": (\n                []\n                if unassessed\n                else [\n                    {\n                        "evidence_id":\n                            "e1",\n                        "identity_use_decision":\n                            "ADMIT_DIRECT",\n                    }\n                ]\n            ),\n            "model_context_cap":\n                24,\n        }\n\n        return trace\n\n    alignment = {\n        "requirement_id":\n            "ERX",\n        "evidence_id":\n            "e1",\n        "alignment_evidence_id":\n            "a1",\n        "retrieval_need_ids":\n            [\n                "ERX.support",\n            ],\n        "argument_admission_channel":\n            "DIRECT",\n        "relation":\n            "SUPPORT",\n    }\n\n    # Discovery procedure complete, candidate disposed.\n    report = evaluate_need_coverage(\n        trace=\n            make_trace(\n                unassessed=\n                    False,\n            ),\n        alignments=[\n            alignment\n        ],\n    )\n\n    assert (\n        report[\n            "procedure_complete"\n        ]\n        is True\n    )\n\n    assert (\n        report[\n            "status"\n        ]\n        == "COMPLETE"\n    )\n\n    assert (\n        report[\n            "proof_coverage_pass"\n        ]\n        is False\n    )\n\n    # Discovery can be procedurally complete while candidate disposition remains\n    # unfinished.\n    report = evaluate_need_coverage(\n        trace=\n            make_trace(\n                unassessed=\n                    True,\n            ),\n        alignments=[],\n    )\n\n    assert (\n        report[\n            "procedure_complete"\n        ]\n        is True\n    )\n\n    assert (\n        report[\n            "status"\n        ]\n        == "LIMITED_TOP_K"\n    )\n\n    assert (\n        report[\n            "proof_coverage_pass"\n        ]\n        is False\n    )\n\n    # Missing expected channel genuinely blocks discovery.\n    report = evaluate_need_coverage(\n        trace=\n            make_trace(\n                unassessed=\n                    False,\n                missing_channel=\n                    True,\n            ),\n        alignments=[\n            alignment\n        ],\n    )\n\n    assert (\n        report[\n            "procedure_complete"\n        ]\n        is False\n    )\n\n    assert (\n        report[\n            "status"\n        ]\n        == "INCOMPLETE_CHANNEL_FAILURE"\n    )\n\n    # Higher level is never guessed from discovery metadata.\n    report = evaluate_need_coverage(\n        trace=\n            make_trace(\n                unassessed=\n                    False,\n                level=\n                    "TARGETED_COMPLETE",\n            ),\n        alignments=[\n            alignment\n        ],\n    )\n\n    assert (\n        report[\n            "procedure_complete"\n        ]\n        is False\n    )\n\n    assert (\n        "HIGHER_COVERAGE_PROCEDURE_OBJECTIVE_NOT_IMPLEMENTED"\n        in report[\n            "limiting_factors"\n        ]\n    )\n\n    print(\n        "coverage_v1.1 self-tests: PASS"\n    )\n    print(\n        "  CANDIDATE_DISCOVERY procedure complete -> does NOT satisfy proof"\n    )\n    print(\n        "  unassessed generated candidate          -> LIMITED_TOP_K"\n    )\n    print(\n        "  missing expected channel               -> channel failure"\n    )\n    print(\n        "  TARGETED_COMPLETE without objective    -> not guessed"\n    )\n'
NEW_MAIN = '\ndef main() -> None:\n    parser = argparse.ArgumentParser()\n\n    parser.add_argument(\n        "--requirement-result",\n        type=Path,\n    )\n\n    parser.add_argument(\n        "--output",\n        type=Path,\n    )\n\n    parser.add_argument(\n        "--self-test",\n        action="store_true",\n    )\n\n    args = parser.parse_args()\n\n    if args.self_test:\n        run_self_tests()\n\n        if (\n            args.requirement_result\n            is None\n        ):\n            return\n\n    if (\n        args.requirement_result\n        is None\n    ):\n        parser.error(\n            "--requirement-result is required "\n            "unless only --self-test is used"\n        )\n\n    result = load_json(\n        args.requirement_result\n    )\n\n    coverage = evaluate_coverage_bundle(\n        result\n    )\n\n    output = (\n        args.output\n        or args.requirement_result.with_name(\n            args.requirement_result.stem\n            + "_coverage_v1_1.json"\n        )\n    )\n\n    save_json(\n        coverage,\n        output,\n    )\n\n    print(\n        "=" * 72\n    )\n    print(\n        "FRECA REQUIREMENT COVERAGE V1.1"\n    )\n    print(\n        "=" * 72\n    )\n\n    for report in coverage[\n        "need_reports"\n    ]:\n        print()\n        print(\n            report[\n                "need_id"\n            ],\n            "requested=",\n            report[\n                "required_level"\n            ],\n            "achieved=",\n            report[\n                "achieved_level"\n            ],\n            "status=",\n            report[\n                "status"\n            ],\n        )\n\n        print(\n            "  procedure_complete:",\n            report[\n                "procedure_complete"\n            ],\n        )\n\n        print(\n            "  proof_coverage_pass:",\n            report[\n                "proof_coverage_pass"\n            ],\n        )\n\n        print(\n            "  candidate universe/context:",\n            (\n                report[\n                    "candidate_count"\n                ],\n                report[\n                    "model_context_count"\n                ],\n            ),\n        )\n\n        print(\n            "  unassessed:",\n            len(\n                report[\n                    "unassessed_candidate_ids"\n                ]\n            ),\n        )\n\n        print(\n            "  channels:",\n            {\n                name:\n                    report[\n                        "channel_reports"\n                    ][\n                        name\n                    ].get(\n                        "mode"\n                    )\n                for name in report[\n                    "expected_channels"\n                ]\n                if name in report[\n                    "channel_reports"\n                ]\n            },\n        )\n\n        print(\n            "  limiting_factors:",\n            report[\n                "limiting_factors"\n            ],\n        )\n\n    print()\n    print(\n        "Requirement summaries:"\n    )\n\n    for item in coverage[\n        "requirement_summaries"\n    ]:\n        print(\n            " ",\n            item[\n                "requirement_id"\n            ],\n            item[\n                "coverage_status"\n            ],\n            "requested=",\n            item[\n                "requested_levels"\n            ],\n        )\n\n    print()\n    print(\n        "Discovery complete     :",\n        coverage[\n            "discovery_complete"\n        ],\n    )\n\n    print(\n        "Proof coverage complete:",\n        coverage[\n            "proof_coverage_complete"\n        ],\n    )\n\n    print(\n        "Next required artifact :",\n        coverage[\n            "next_required_artifact"\n        ],\n    )\n\n    print(\n        "Adverse inference      :",\n        coverage[\n            "adverse_inference_allowed"\n        ],\n    )\n\n    print(\n        "Saved                  :",\n        output,\n    )\n\n\nif __name__ == "__main__":\n    main()\n'


def replace_top_level_function(
    src: str,
    name: str,
    replacement: str,
) -> str:
    tree = ast.parse(
        src
    )

    matches = [
        node
        for node in tree.body
        if isinstance(
            node,
            (
                ast.FunctionDef,
                ast.AsyncFunctionDef,
            ),
        )
        and node.name
        == name
    ]

    if len(
        matches
    ) != 1:
        raise RuntimeError(
            f"Expected exactly one top-level function {name}, "
            f"found {len(matches)}"
        )

    node = matches[
        0
    ]

    lines = src.splitlines(
        keepends=True
    )

    lines[
        node.lineno - 1:
        node.end_lineno
    ] = [
        replacement.rstrip()
        + "\n\n"
    ]

    return "".join(
        lines
    )


